(4753208, 681198, 33672, '<td valign="top">I''m laughing to hard to comment further.  Looks like a painting one might see in an old west brothel..;P</td>', 'I''m laughing to hard to comment further.  Looks like a painting one might see in an old west brothel..;P', '2008-06-06 02:27:56.000000', NULL, 1),
(4753209, 684064, 33672, '<td valign="top">I like the diagonal lines in this.</td>', 'I like the diagonal lines in this.', '2008-06-06 02:28:43.000000', NULL, 1),
(4753212, 682785, 33672, '<td valign="top">Beautiful and emotive.</td>', 'Beautiful and emotive.', '2008-06-06 02:30:06.000000', NULL, 1),
