(4756900, 677660, 67697, '<td valign="top">That''s a crazy dog.  Great motion capture.</td>', 'That''s a crazy dog.  Great motion capture.', '2008-06-08 00:12:45.000000', NULL, 1),
(4756902, 679028, 59740, '<td valign="top">Very nice. The mist beautifully highlights the real couple.</td>', 'Very nice. The mist beautifully highlights the real couple.', '2008-06-08 00:13:21.000000', NULL, 1),
